/*orion:native-match:payload:h2h-totals*/
 WITH projected AS MATERIALIZED (
 SELECT t.match_id AS witness,t.home_wins::text,t.home_wins_state,t.draws::text,t.draws_state,t.away_wins::text,t.away_wins_state,t.total_matches::text,t.total_matches_state
 FROM football.match_h2h_summaries t WHERE (t.match_id,t.source_id,t.feature_code,t.variant_key,t.recorded_from_gen)=($1::bigint,$2::bigint,$3::text,$4::text,$5::bigint) LIMIT 2), budget AS (
   SELECT coalesce(sum(octet_length(row_to_json(p)::text)),0)>4194304 AS exceeded FROM projected p
 ) SELECT p.*,budget.exceeded FROM budget LEFT JOIN projected p ON NOT budget.exceeded

